  });

  protected readonly dueTotal = computed(() =>
    sumAmounts(this.people().map((p) => this.personDueTotal(p)).filter((d) => d !== NO_RATE)),
  );
  protected readonly editingId = signal<number | null>(null);
  /** The version of the person the editor loaded. */
  private editingVersion: number | null = null;
  /** Whether a submit is waiting on the server; another submit is ignored until it answers. */
  private submitting = false;
  protected readonly formError = signal<string | null>(null);
  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
    grade: new FormControl<Grade>('A', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.formError.set(null));
    // Re-read the sheet's people and their claims from the store each time a sheet is loaded.
    toObservable(this.session.sheetId)
      .pipe(
        switchMap((id) =>
          id
            ? forkJoin({ people: this.api.list(id), claims: this.claimsApi.list(id), rates: this.ratesApi.list(id) })
            : of({ people: [] as Person[], claims: [] as Claim[], rates: [] as Rate[] }),
        ),
      )
      .subscribe(({ people, claims, rates }) => {
        this.people.set(people);
        this.claims.set(claims);
        this.rates.set(rates);
        this.reset();
      });
  }

  protected claimsOf(personId: number): Claim[] {
    return this.claimsByPerson().get(personId) ?? [];
  }

  protected claimed(personId: number): string {
    return sumAmounts(this.claimsOf(personId).filter(counts).map((c) => c.amount));
  }

  /** The sum of the dues of the claims the person has that count (n/a ones skipped), 0.00 with none. A
   * person whose grade has no rate in force on the sheet's today shows n/a, unless a settled claim keeps a
   * figure. */
  protected personDueTotal(person: Person): string {
    const counted = this.claimsOf(person.id).filter(counts);
    const frozen = counted.some((c) => c.due !== null);
    if (!this.rateByGrade().has(person.grade) && !frozen) return NO_RATE;
    return sumAmounts(counted.map((c) => claimDue(c, this.rates(), person.grade)).filter((d) => d !== NO_RATE));
  }

  protected rateSaved(rate: Rate): void {
    this.rates.update((rs) => [...rs.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate]);
  }

  protected claimSaved(claim: Claim): void {
    this.claims.update((cs) =>
      cs.some((c) => c.id === claim.id) ? cs.map((c) => (c.id === claim.id ? claim : c)) : [claim, ...cs],
    );
  }

  protected edit(person: Person): void {
    this.editingId.set(person.id);
    this.editingVersion = person.version;
    this.form.setValue({ name: person.name, grade: person.grade }, { emitEvent: false });
    this.formError.set(null);
  }

  protected reset(): void {
    this.editingId.set(null);
    this.editingVersion = null;
    this.form.reset({ name: '', grade: 'A' }, { emitEvent: false });
    this.formError.set(null);
  }

  protected submit(): void {
    if (this.submitting) return;
    this.formError.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) {
      this.formError.set('Load a sheet first.');
      return;
    }
    const value = this.form.getRawValue();
    if (!value.name.trim()) {
      this.formError.set('Type a name for the person.');
      return;
    }
    const id = this.editingId();
    this.submitting = true;
    const done = () => (this.submitting = false);
    if (id === null) {
      this.api.add(sheetId, value).subscribe({
        next: (p) => {
          done();
          if (this.session.sheetId() === sheetId) this.people.update((ps) => [...ps, p]);
          this.reset();
        },
        error: (e: HttpErrorResponse) => {
          done();
          this.formError.set(this.refusal(e, 'Could not add that person.'));
        },
      });
    } else {
      this.api.update(sheetId, id, { ...value, version: this.editingVersion ?? undefined }).subscribe({
        next: (p) => {
          done();
          if (this.session.sheetId() === sheetId) this.people.update((ps) => ps.map((x) => (x.id === p.id ? p : x)));
          this.reset();
        },
        error: (e: HttpErrorResponse) => {
          done();
          if (e.status === 412) {
            this.formError.set('Someone else has saved this person since you opened it. Their values are shown.');
            this.showCurrent(sheetId, id);
          } else {
            this.formError.set(this.refusal(e, 'Could not save that person.'));
          }
        },
      });
    }
  }

  /** Re-read the person from the store and show their current values in the editor, keeping its error. */
  private showCurrent(sheetId: string, id: number): void {
    this.api.list(sheetId).subscribe((people) => {
      if (this.session.sheetId() !== sheetId) return;
      this.people.set(people);
      const current = people.find((p) => p.id === id);
      if (current && this.editingId() === id) {
        this.editingVersion = current.version;
        this.form.setValue({ name: current.name, grade: current.grade }, { emitEvent: false });
      }
    });
  }

  private refusal(e: HttpErrorResponse, fallback: string): string {
    return e.status === 409 ? 'That name is already in use on this sheet.' : fallback;
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Session } from '../../core/session';
import { Grade } from '../people/people-api';
import { Rate, dueOf, rateOn } from '../rates/rates-api';

export interface Claim {
  id: number;
  personId: number;
  /** With two decimals, e.g. "10.00". */
  amount: string;
  /** yyyy-mm-dd */
  date: string;
  note: string;
  status: ClaimStatus;
  /** The sheet's number for the claim, given when it is opened; null while a draft or once voided. */
  number: number | null;
  /** What was due when the claim was settled, with two decimals; null while it is live (not settled, or
   * settled when its grade had no rate). */
  due: string | null;
  /** Who opened the claim; null while it is a draft. */
  openedBy: string | null;
}

/** A claim starts as DRAFT, is opened and then settled; a DRAFT or OPEN claim can be voided. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** The status changes a person can ask for on a claim. */
export type ClaimAction = 'open' | 'settle' | 'void';

/** Only OPEN and SETTLED claims count toward what is claimed and due. */
export function counts(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'SETTLED';
}

/** A settled claim's due is the figure it was settled at; any other is due at the rate its grade has now
 * in force on the claim's date (n/a when there is none). */
export function claimDue(claim: Claim, rates: readonly Rate[], grade: Grade): string {
  return claim.due ?? dueOf(claim.amount, rateOn(rates, grade, claim.date));
}

export interface ClaimForm {
  amount: string;
  /** Null for the sheet's today. */
  date: string | null;
  note: string;
}

/** The sum of claim amounts with two decimals, added up in cents so no rounding creeps in. */
export function sumAmounts(amounts: string[]): string {
  const cents = amounts.reduce((sum, a) => {
    const [whole, frac = ''] = a.split('.');
    return sum + Number(whole) * 100 + Number(frac.padEnd(2, '0'));
  }, 0);
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

// The claims people make on the active sheet, read and changed through the server.
@Injectable({ providedIn: 'root' })
export class ClaimsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheetId: string): Observable<Claim[]> {
    return this.http.get<Claim[]>(`${this.url(sheetId)}/claims`, { headers: this.headers() });
  }

  add(sheetId: string, personId: number, form: ClaimForm): Observable<Claim> {
    return this.http.post<Claim>(`${this.url(sheetId)}/people/${personId}/claims`, form, {
      headers: this.headers(),
    });
  }

  update(sheetId: string, id: number, form: ClaimForm): Observable<Claim> {
    return this.http.put<Claim>(`${this.url(sheetId)}/claims/${id}`, form, { headers: this.headers() });
  }

  changeStatus(sheetId: string, id: number, action: ClaimAction): Observable<Claim> {
    return this.http.post<Claim>(`${this.url(sheetId)}/claims/${id}/${action}`, null, { headers: this.headers() });
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, input, output, signal, untracked } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { Rate } from '../rates/rates-api';
import { Grade } from '../people/people-api';
import { Claim, ClaimAction, ClaimsApi, claimDue } from './claims-api';

const AMOUNT = /^\d{1,10}(\.\d{1,2})?$/;

// One person's claims, newest first, and the one form that adds a claim for them or, once a
// claim's editor is opened, saves changes to it.
@Component({
  selector: 'app-claims',
  imports: [ReactiveFormsModule],
  template: `
    <form [formGroup]="form" (ngSubmit)="submit()" data-testid="claim-form">
      <label [for]="'claim-form-amount-' + personId()">Amount</label>
      <input
        [id]="'claim-form-amount-' + personId()"
        data-testid="claim-form-amount"
        inputmode="decimal"
        formControlName="amount"
      />
      <label [for]="'claim-form-date-' + personId()">Date</label>
      <input [id]="'claim-form-date-' + personId()" type="date" data-testid="claim-form-date" formControlName="date" />
      <label [for]="'claim-form-note-' + personId()">Note</label>
      <input [id]="'claim-form-note-' + personId()" data-testid="claim-form-note" formControlName="note" />
      <button type="submit" data-testid="claim-form-submit">
        {{ editingId() === null ? 'Add claim' : 'Save claim' }}
      </button>
      @if (editingId() !== null) {
        <button type="button" data-testid="claim-form-cancel" (click)="reset()">Cancel</button>
      }
    </form>
    @if (formError(); as e) {
      <p role="alert" data-testid="claim-form-error">{{ e }}</p>
    }
    @if (claims().length > 0) {
      <table data-testid="claim-list">
        <caption class="visually-hidden">Claims by {{ personName() }}</caption>
        <thead>
          <tr>
            <th scope="col">No.</th>
            <th scope="col">Amount</th>
            <th scope="col">Date</th>
            <th scope="col">Note</th>
            <th scope="col">Due</th>
            <th scope="col">Status</th>
            <th scope="col">Opened by</th>
            <th scope="col"><span class="visually-hidden">Actions</span></th>
          </tr>
        </thead>
        <tbody>
          @for (c of claims(); track c.id) {
            <tr [attr.data-testid]="'claim-row-' + c.id">
              <td data-testid="claim-number">{{ c.number ?? '' }}</td>
              <td data-testid="claim-amount">{{ c.amount }}</td>
              <td data-testid="claim-date">{{ c.date }}</td>
              <td data-testid="claim-note">{{ c.note }}</td>
              <td data-testid="claim-due">{{ due(c) }}</td>
              <td data-testid="claim-status">{{ c.status }}</td>
              <td data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</td>
              <td>
                <button
                  type="button"
                  data-testid="claim-edit"
                  [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date"
                  (click)="edit(c)"
                >
                  Edit
                </button>
                @for (a of actions; track a.action) {
                  <button
                    type="button"
                    [attr.data-testid]="'claim-' + a.action"
                    [attr.aria-label]="a.label + ' claim of ' + c.amount + ' on ' + c.date"
                    (click)="changeStatus(c, a.action)"
                  >
                    {{ a.label }}
                  </button>
                }
                @if (claimError()?.id === c.id) {
                  <p role="alert" data-testid="claim-error">{{ claimError()?.message }}</p>
                }
              </td>
            </tr>
          }
        </tbody>
      </table>
    }
  `,
})
export class Claims {
  private readonly session = inject(Session);
  private readonly api = inject(ClaimsApi);

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  /** This person's claims, newest first. */
  readonly claims = input.required<Claim[]>();
  /** This person's grade, and the sheet's rates. */
  readonly grade = input.required<Grade>();
  readonly rates = input<readonly Rate[]>([]);
  /** A claim was added or saved. */
  readonly saved = output<Claim>();

  protected readonly actions: { action: ClaimAction; label: string }[] = [
    { action: 'open', label: 'Open' },
    { action: 'settle', label: 'Settle' },
    { action: 'void', label: 'Void' },
  ];
  protected readonly editingId = signal<number | null>(null);
  /** The error of the last action taken on a claim, shown on that claim's row. */
  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
  protected readonly formError = signal<string | null>(null);
  /** Whether a submit is waiting on the server; another submit is ignored until it answers. */
  private submitting = false;
  protected readonly form = new FormGroup({
    amount: new FormControl('', { nonNullable: true }),
    date: new FormControl('', { nonNullable: true }),
    note: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.formError.set(null));
    // A new claim is dated the sheet's today unless another date is picked.
    effect(() => {
      const today = this.session.today() ?? '';
      untracked(() => {
        if (this.editingId() === null && !this.form.controls.date.dirty) {
          this.form.controls.date.setValue(today, { emitEvent: false });
        }
      });
    });
  }

  /** A settled claim shows the due it was settled at; any other is due at the rate its grade has now in
   * force on the claim's date. */
  protected due(claim: Claim): string {
    return claimDue(claim, this.rates(), this.grade());
  }

  protected changeStatus(claim: Claim, action: ClaimAction): void {
    this.claimError.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    this.api.changeStatus(sheetId, claim.id, action).subscribe({
      next: (c) => {
        if (this.session.sheetId() === sheetId) this.saved.emit(c);
      },
      error: (e: HttpErrorResponse) =>
        this.claimError.set({
          id: claim.id,
          message:
            e.status === 403
              ? 'You opened that claim, so someone else must settle it.'
              : e.status === 409
              ? 'That claim\'s status does not allow that change.'
              : e.status === 404
                ? 'That claim is no longer on this sheet.'
                : 'Could not change that claim\'s status.',
        }),
    });
  }

  protected edit(claim: Claim): void {
    this.claimError.set(null);
    this.editingId.set(claim.id);
    this.form.setValue({ amount: claim.amount, date: claim.date, note: claim.note }, { emitEvent: false });
    this.formError.set(null);
  }

  protected reset(): void {
    this.editingId.set(null);
    this.form.reset({ amount: '', date: this.session.today() ?? '', note: '' }, { emitEvent: false });
    this.formError.set(null);
  }

  protected submit(): void {
    if (this.submitting) return;
    this.formError.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) {
      this.formError.set('Load a sheet first.');
      return;
    }
    const value = this.form.getRawValue();
    const amount = value.amount.trim();
    if (!AMOUNT.test(amount)) {
      this.formError.set('Type an amount of 0.00 or more, with up to two decimals.');
      return;
    }
    const form = { amount, date: value.date || null, note: value.note.trim() };
    const id = this.editingId();
    const request = id === null ? this.api.add(sheetId, this.personId(), form) : this.api.update(sheetId, id, form);
    this.submitting = true;
    request.subscribe({
      next: (c) => {
        this.submitting = false;
        if (this.session.sheetId() === sheetId) this.saved.emit(c);
        this.reset();
      },
      error: (e: HttpErrorResponse) => {
        this.submitting = false;
        this.formError.set(e.status === 404 ? 'That person or claim is no longer on this sheet.' : 'Could not save that claim.');
      },
    });
  }
}

